import{ax as s,A as e,aQ as i,z as t}from"./chunks/framework.BWRXlwpK.js";const b=JSON.parse('{"title":"ADB reverse 端口转发解决不同网段 App 无法调用接口的问题","description":"电脑网口与手机 WiFi 不在同一网段时，Android App 无法访问电脑本地接口。本文讲解 adb reverse 端口转发原理与步骤，通过 USB 让手机直接访问电脑 localhost 服务，适用于 Android App 和 WebView 调试场景。","frontmatter":{"title":"ADB reverse 端口转发解决不同网段 App 无法调用接口的问题","description":"电脑网口与手机 WiFi 不在同一网段时，Android App 无法访问电脑本地接口。本文讲解 adb reverse 端口转发原理与步骤，通过 USB 让手机直接访问电脑 localhost 服务，适用于 Android App 和 WebView 调试场景。"},"headers":[],"relativePath":"blog/adb-reverse.md","filePath":"blog/adb-reverse.md","lastUpdated":1788144986000}'),p={name:"blog/adb-reverse.md"};function l(n,a,d,h,r,o){return t(),e("div",null,a[0]||(a[0]=[i(`<h1 id="adb-reverse-端口转发解决不同网段-app-无法调用接口的问题" tabindex="-1">ADB reverse 端口转发解决不同网段 App 无法调用接口的问题 <a class="header-anchor" href="#adb-reverse-端口转发解决不同网段-app-无法调用接口的问题" aria-label="Permalink to &quot;ADB reverse 端口转发解决不同网段 App 无法调用接口的问题&quot;">​</a></h1><blockquote><p>本文介绍 <strong>adb reverse（端口转发）</strong> 的用法，解决 Android 手机与电脑不在同一网段时，<strong>App 无法访问电脑本地接口</strong>（localhost 后台服务）的问题。</p></blockquote><p>换新公司后网口和 wifi 不在一个网段，导致我的接口无法正常调用。无线网卡还没到只能先用这种方式凑合一下了。</p><p><strong>适用场景</strong>：手机 App 联调时，电脑连的是网口、手机连的是 WiFi，两者不在同一网段，App 直接访问电脑 IP 会超时。此时可以用 USB 连接 + <code>adb reverse</code> 把手机端口转发到电脑端口。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>1.手机连接usb</li><li>2.手机打开开发者模式</li><li>3.接口地址</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-确认adb正常" tabindex="-1">1.确认adb正常 <a class="header-anchor" href="#_1-确认adb正常" aria-label="Permalink to &quot;1.确认adb正常&quot;">​</a></h3><p>在 CMD / PowerShell 中输入</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devices</span></span></code></pre></div><p>确认adb是否正常。</p><p>正常来说应该看到：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">List</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devices</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attached</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xxxxx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    device</span></span></code></pre></div><p>如果没有：</p><ul><li>检查电脑和手机的USB连接是否正常</li><li>检查手机USB调试是否开启，部分手机还需要开启 <code>USB调试（安全设置）</code></li><li>允许 RSA 授权</li></ul><h3 id="_2-确认-后台服务-本地可访问" tabindex="-1">2.确认 后台服务 本地可访问 <a class="header-anchor" href="#_2-确认-后台服务-本地可访问" aria-label="Permalink to &quot;2.确认 后台服务 本地可访问&quot;">​</a></h3><p>比如你的后台地址是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8080</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或</span></span>
<span class="line"><span></span></span>
<span class="line"><span>http://localhost:8080/xxx/api</span></span></code></pre></div><p>要确认是否运行正常</p><h3 id="_3-开启-reverse-端口转发" tabindex="-1">3.开启 reverse 端口转发 <a class="header-anchor" href="#_3-开启-reverse-端口转发" aria-label="Permalink to &quot;3.开启 reverse 端口转发&quot;">​</a></h3><p>因为我的后台端口用的是 <code>8080</code> 所以这里转发的也要是 <code>8080</code></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reverse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:8080</span></span></code></pre></div><p><strong>命令解释</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>adb reverse [手机端端口] [电脑端端口]</span></span></code></pre></div><p>这里就是 <code>手机 8080</code> 转发到 <code>电脑 8080</code>。</p><h3 id="_4-验证是否成功" tabindex="-1">4.验证是否成功 <a class="header-anchor" href="#_4-验证是否成功" aria-label="Permalink to &quot;4.验证是否成功&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reverse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span></code></pre></div><p>正常会看到</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcp:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:8080</span></span></code></pre></div><p>这时再用手机访问应该就可以了。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>1.使用这种方式期间USB不能断开</li><li>2.如果断开USB，需要重新执行上述命令进行连接</li><li>3.此方法仅适用于Android App、Android WebView，不适用于浏览器（Chrome/Edge/等...）</li></ul>`,32)]))}const k=s(p,[["render",l]]);export{b as __pageData,k as default};
